_lesson("https://www.opm.gov/policy-data-oversight/assessment-and-selection/other-assessment-methods/work-samples-and-simulations/",
        "recruiting", "Work samples: choose and score job-relevant tasks", "US Office of Personnel Management",
        "Public assessment-method guidance on representative tasks, entry competencies, trained observation and keeping simulations current. General method knowledge; no employment-law or subgroup-outcome guarantees.",
        ("Work Samples and Simulations", "Considerations"), [
    ("representative", "work-sample-purpose", 1, "What should a work sample resemble?", "Important tasks performed in the job", ["Only an unrelated academic puzzle", "Only the recruiter's favourite hobby", "Only a candidate's self-rating"], "Representative tasks give relevant performance evidence."),
    ("entry", "work-sample-entry", 2, "When are work samples most appropriate under this guidance?", "When the tested competency is expected on entry", ["Whenever the skill will only be taught after selection", "Only after an employee retires", "Only when no job tasks can be identified"], "Testing an untaught future skill can be inappropriate for entry selection."),
    ("scoring", "work-sample-scoring", 1, "How can work-sample performance be scored?", "Trained observation and relevant task results", ["Candidate self-rating alone", "Observer impressions gathered without common performance criteria", "Completion order without reviewing the quality or accuracy of the work"], "Observed behaviour and outcomes provide assessable evidence."),
    ("design", "work-sample-purpose", 3, "A role requires accurate stock-record updates. Which work sample is most relevant?", "Update a fictional stock record and assess accuracy", ["Recite product names", "Explain warehouse terminology without entering or checking any stock changes", "Write a general description of inventory duties without working with records"], "The sample should mirror the competency required by the role."),
    ("train-later", "work-sample-entry", 3, "A company will teach a proprietary system after hiring. Which concern most directly follows the work-sample guidance?", "The test may assess a skill not expected at entry", ["The test must be appropriate because its interface is proprietary", "Any future training makes all assessment unnecessary", "Unfamiliarity with the system establishes inability to learn"], "The method is strongest for competencies required at entry."),
    ("update", "work-sample-maintenance", 3, "The job moves from paper forms to digital records. What should happen to a paper-only work sample?", "Review and update it to reflect the actual work", ["Keep it unchanged solely for historical consistency", "Assume any old task remains equally representative", "Replace scoring criteria with speed alone"], "Changes in work can make an assessment outdated."),
])

_lesson("https://openstax.org/books/principles-marketing/pages/15-1-personal-selling-and-its-role-in-the-promotion-mix", "sales",
        "Choose personal selling for complex customer needs", "OpenStax",
        "One-to-one selling, relationship development and fit for complex or customisable products. Original short cases exclude publisher exercises and do not claim observed sales competence.",
        ("Personal Selling Defined", "Relationship Selling", "When to Use Personal Selling"), [
    ("dialogue", "personal-selling-channel", 1, "A representative discusses an individual buyer's requirements directly with that buyer. Which communication approach is this?", "Personal selling", ["An untargeted mass advertisement", "An anonymous public billboard", "A general press release with no dialogue"], "Personal selling involves a direct buyer-representative interaction."),
    ("advisor", "personal-selling-relationship", 2, "What role does relationship selling seek to develop with the buyer?", "A trusted adviser who understands buyer needs", ["An order taker", "A representative who repeats one pitch without asking about the buyer's work", "A spokesperson who handles the first sale without learning the customer's requirements"], "Trust and understanding support a suitable continuing relationship."),
    ("custom", "personal-selling-fit", 1, "Why can a customisable product benefit from personal selling?", "Match options to the buyer's requirements", ["Sell one standard package", "Use the same configuration for every buyer regardless of how they will use it", "Present the full options catalogue without discussing which choices fit the buyer"], "Product variation can require individual explanation and selection."),
    ("complex-equipment", "personal-selling-fit", 3, "A laboratory considers equipment with several configurations and significant training needs. Which communication best fits the reading?", "An expert explains options for the lab's needs", ["A generic product banner", "A price sheet that lists each configuration without explaining training or tradeoffs", "A preselected setup sent to the lab before gathering its requirements"], "Complex decisions can benefit from tailored explanation."),
    ("relationship", "personal-selling-relationship", 3, "A buyer may need support and upgrades over several years. What should the seller prioritise?", "Build trust around the buyer's ongoing needs", ["Maximise the first order", "Prioritise the highest-price bundle without confirming how the buyer will use it", "Treat the sale as complete without planning for training, support or upgrades"], "Relationship selling considers the customer beyond one transaction."),
    ("channel-choice", "personal-selling-channel", 3, "A company chooses its promotion mix. What should determine the role of personal selling?", "Its marketing goals, product, target segment and message", ["Using the same channel for every product regardless of context", "Only the number of representatives already hired", "Only which channel has the shortest name"], "Channel choice should fit the strategy and buying situation."),
], "#main-content")

_lesson("https://openstax.org/books/principles-marketing/pages/15-7-ethical-issues-in-personal-selling-and-sales-promotion", "sales",
        "Honest selling: claims, expenses and transparent offers", "OpenStax",
        "Honest product claims, documented expenses, sales-data integrity and clear promotional prices/terms. Fictional cases exclude jurisdictional bribery law and historical company incidents.",
        ("Ethical Issues in Personal Selling", "Misuse of Company Credit Cards or Expense Accounts", "Inflating Sales Data", "Hidden Fees", "Ambiguous Terms and Conditions"), [
    ("trust", "selling-integrity", 1, "What supports a long-term sales relationship?", "Honest claims and integrity", ["Concealing a limitation until after purchase", "Changing a promise after payment", "Using unsupported claims to reach a target"], "Trust depends on truthful dealing."),
    ("expenses", "selling-expense-records", 2, "Which practice supports accountability for sales expenses?", "Clear expense policies and receipts", ["Duplicate claims without records", "Treating personal purchases as client costs", "Approving every amount without checking"], "Documentation and policy help prevent expense misuse."),
    ("stuffing", "selling-data-integrity", 1, "Pushing more products into a distribution channel than it can sell to inflate shipment-based sales is called what?", "Channel stuffing", ["Customer needs analysis", "Independent expense reconciliation", "A transparent product demonstration"], "Shipment inflation can mask unsustainable demand."),
    ("claim", "selling-integrity", 3, "A prospect asks whether a tool supports a feature that is still unconfirmed. What should the representative do?", "Verify the capability and state its limits", ["Promise it for now", "Present the roadmap entry as a feature the customer can use today", "Leave the question unanswered but include the feature in the written offer"], "An unsupported promise damages truthful selling."),
    ("fees", "selling-offer-transparency", 3, "An offer advertises 80 fictional units but adds an unavoidable 25-unit fee late in checkout. What concern should be corrected?", "The advertised offer obscures the actual required cost", ["The fee must be irrelevant because it is added later", "Only the headline price affects understanding", "An unavoidable fee cannot influence the purchase decision"], "Hidden required charges undermine a clear offer."),
    ("terms", "selling-offer-transparency", 3, "A promotion's key limitation is written ambiguously. Which change supports the customer relationship?", "Explain the limitation before commitment", ["Mention it after purchase", "Keep the same ambiguous wording and shorten the time available to read it", "Ask the customer to accept the offer before showing the conditions that limit it"], "Clear terms help customers understand the offer."),
], "#main-content")

_lesson("https://opentextbc.ca/introtourism2e/chapter/loyalty-and-customer-relationships/", "success",
        "Customer loyalty: records, touchpoints and repeat value", "BCcampus Open Education",
        "Customer retention, repeat/referral value, maintained preference records and coordinated touchpoints. Qualitative relationship knowledge; no universal acquisition-cost ratio or complete CLV financial model.",
        ("Loyalty and Customer Relationships", "Maintaining a customer database", "Communicating with customers"), [
    ("retention", "customer-retention", 1, "Retaining a customer means focusing on what?", "Continue an existing customer relationship", ["Acquire a new customer", "Track a first-time visit without following what happens to the relationship afterwards", "Replace the existing customer base by focusing exclusively on new enquiries"], "Retention considers the relationship beyond the first sale."),
    ("lifetime", "customer-long-term", 2, "A customer-lifetime perspective considers what?", "Value across the relationship", ["First sale value alone", "The largest invoice without considering other purchases or future interactions", "The most recent campaign response without the customer's earlier history"], "The perspective extends beyond one purchase."),
    ("records", "customer-records", 1, "What supports personalised service for returning customers?", "Current, relevant customer preferences and history", ["The last queue position", "A separate record for each visit with no link to earlier preferences", "Old preference information used indefinitely without checking for changes"], "Maintained records support continuity."),
    ("touchpoints", "customer-touchpoints", 3, "A company sends friendly follow-ups but ignores poor in-person service. What should relationship planning address?", "Improve service across the customer touchpoints", ["Send more follow-ups", "Update the look of the loyalty programme while keeping the in-person problems unchanged", "Increase acquisition activity without addressing how current customers are served"], "Loyal relationships depend on more than one contact point."),
    ("preference-update", "customer-records", 3, "A returning customer says an old preference has changed. What action best supports future service?", "Update the relevant record and use the current preference", ["Keep applying the old preference because it was recorded first", "Create unrelated duplicates without correcting the history", "Assume preferences can never change"], "Useful customer records should stay current."),
    ("referral", "customer-long-term", 3, "A satisfied repeat customer recommends the business to someone else. What value has the relationship produced beyond its own purchases?", "A potential customer referral", ["Proof that every new lead will convert", "A guarantee that acquisition work is unnecessary", "An automatic reduction of every service cost"], "Loyal customers can influence other prospective customers."),
])

_lesson("https://opentextbc.ca/introtourism2e/chapter/exceeding-expectations/", "success",
        "Service quality: expectations and the RATER dimensions", "BCcampus Open Education",
        "Service expectations versus perceptions, reliability, assurance, tangibles, empathy and responsiveness. Introductory knowledge only; no numerical SERVQUAL scoring model or automatic satisfaction guarantee.",
        ("Customer Service and Competition: The Customer-Oriented Organization", "SERVQUAL", "Customer relationship management touch points"), [
    ("gap", "service-quality-expectations", 1, "The described SERVQUAL approach compares customer perceptions with what?", "Customer expectations", ["Only the number of employees", "Only competitors' logos", "Only the organisation's rent"], "Quality is examined relative to expected service."),
    ("reliability", "service-quality-reliability", 2, "Consistently delivering the promised service relates most directly to which dimension?", "Reliability", ["Tangibles", "Empathy", "Assurance"], "Reliability concerns consistent service performance."),
    ("tangibles", "service-quality-tangibles", 1, "Physical facilities and equipment belong most directly to which dimension?", "Tangibles", ["Responsiveness", "Empathy", "Reliability"], "Tangibles are visible physical aspects of the service."),
    ("assurance", "service-quality-assurance", 3, "A staff member answers a difficult service question knowledgeably and courteously, helping the customer feel confident. Which dimension is illustrated?", "Assurance", ["Tangibles", "Only physical convenience", "Only response speed"], "Knowledge and courtesy can convey trust and confidence."),
    ("empathy", "service-quality-empathy", 3, "A representative takes care to understand a customer's individual circumstances before suggesting an option. Which dimension fits best?", "Empathy", ["Tangibles", "Only standardised processing speed", "Only consistency of opening hours"], "Empathy involves caring individual attention."),
    ("responsiveness", "service-quality-responsiveness", 3, "A service team promptly offers help when a customer needs assistance. Which dimension is most directly demonstrated?", "Responsiveness", ["Tangibles", "Only account-record completeness", "Only the building's appearance"], "Responsiveness is willingness to help and provide prompt service."),
])

_lesson("https://trailhead.salesforce.com/content/learn/modules/accounts_contacts_lightning_experience/understand-account-and-contact-relationships-lightning",
        "account-management", "Connect contacts, account hierarchies and account teams", "Salesforce Trailhead",
        "Public unit on direct/indirect contact relationships, parent-account hierarchies and internal account-team roles. No account setting, permission change or hands-on challenge is required for the reading/checks.",
        ("Contacts to Multiple Accounts", "Define Company Relationships with Account Hierarchies", "Define Employee Roles with Account Teams"), [
    ("multiple", "account-contact-relations", 1, "Why relate one contact to multiple accounts?", "Connect one person to several accounts without duplicates", ["Replace accounts with contacts", "Create a separate copy of the person's record each time they deal with a different account", "Make account relationships implicit by recording the person's name in each company's notes"], "A person can have several business relationships."),
    ("parent", "account-hierarchy", 2, "What does an account's Parent Account help represent?", "Its position in a company account hierarchy", ["The contact's manager", "The reporting relationship between internal colleagues assigned to the customer", "The link between the latest customer activity and the person who recorded it"], "Account hierarchies describe relationships between companies."),
    ("team", "account-team", 1, "What does an account team describe?", "Internal colleagues who serve the account", ["The customer's subsidiaries", "A list of external people at the customer company without internal role assignments", "The set of products linked to all opportunities for the company"], "Account-team roles coordinate the people serving the account."),
    ("consultant", "account-contact-relations", 3, "A consultant works with two customer companies. Which feature models this without duplicate contact records, when enabled?", "Contacts to Multiple Accounts", ["A separate duplicate person for every interaction", "One account record renamed after each meeting", "An unlinked note replacing both company relationships"], "The feature stores the person's additional account relationships."),
    ("locations", "account-hierarchy", 3, "Separate customer branches have their own cases and opportunities, but reporting must also show the group. What arrangement fits the unit?", "Link separate location accounts in a hierarchy", ["Use one shared contact", "Keep branches as unrelated accounts with no link for reporting across the group", "Collapse every branch into a single record and discard location-specific histories"], "Separate accounts can retain local detail while a hierarchy connects the group."),
    ("role-access", "account-team", 3, "Sales and support colleagues need different responsibilities for one customer. What does the unit suggest account teams can provide?", "Defined roles with appropriate access to account-related records", ["Identical unrestricted access as an unavoidable rule", "No distinction between customer contacts and internal colleagues", "Automatic configuration without administrator setup"], "Account teams support different roles and access levels when configured."),
])

_lesson("https://www.atlassian.com/team-playbook/plays/5-whys", "analysis",
        "5 Whys: investigate causes and verify a useful action", "Atlassian",
        "A focused problem statement, iterative causal questioning, no-blame investigation and testing whether addressing the proposed root cause prevents recurrence. Not proof of causation from repetition alone.",
        ("Identify your problem", "Set the stage", "Ask Why", "Identify the underlying cause", "Propose solutions"), [
    ("start", "five-whys-problem", 1, "What should the team bring to a 5 Whys session?", "One clear problem statement", ["Only a preferred solution with no defined problem", "Every unrelated complaint at once", "A list of people to blame"], "A focused problem anchors the investigation."),
    ("chain", "five-whys-chain", 2, "How does the next Why normally build on the previous step?", "Use the previous answer as the next problem to investigate", ["Return to an unrelated issue each time", "Repeat identical words without examining the answer", "Choose a solution before considering causes"], "The sequence follows an emerging causal explanation."),
    ("count", "five-whys-depth", 1, "Must exactly five questions always establish the root cause?", "No, fewer or more may be needed", ["Yes, the fifth answer is automatically proven", "Yes, evidence stops mattering after five questions", "No questions may be asked after the first answer"], "The page explicitly allows different questioning depth."),
    ("verify", "five-whys-verify", 3, "A team names a suspected root cause. What should it examine before treating the explanation as useful?", "Whether addressing it would prevent the initial problem recurring", ["Only whether the answer sounds decisive", "Only whether five questions were counted", "Whether one person can be assigned blame"], "The proposed cause should explain prevention of recurrence."),
    ("blame", "five-whys-investigation", 3, "The first answer is 'someone was careless'. What should a no-blame investigation do next?", "Explore the decisions and conditions contributing to the event", ["End the session because a person was named", "Treat blame as sufficient evidence", "Suppress other participants' explanations"], "The process investigates underlying conditions rather than stopping at blame."),
    ("action", "five-whys-actions", 3, "The group selects a corrective solution. What makes follow-through concrete?", "An owner, an expected follow-up time and progress tracking", ["Only keeping the solution in private notes", "Only agreeing it sounds promising", "Closing the issue before anyone acts"], "Owned actions and follow-up connect analysis to improvement."),
])

_lesson("https://opentextbc.ca/introtourism2e/chapter/4-operations/", "hospitality",
        "Food-service operations: location, costs and capacity", "BCcampus Open Education",
        "Food/beverage operating costs, perishability, site analysis and existing-capacity revenue versus market share. Historical regional margins and wage/tax statements are excluded.",
        ("Location", "Cost Control", "Sales and Marketing"), [
    ("prime", "food-service-costs", 1, "Which costs are described as prime food-service operating costs?", "Food, beverage and payroll", ["Only building depreciation and insurance", "Only advertising and legal fees", "Only equipment resale values"], "The reading groups food, beverage and labour as prime costs."),
    ("site", "food-service-location", 2, "Which factors belong in restaurant site analysis?", "Traffic, visibility, accessibility and the target patrons", ["Only how low the rent is", "Only the previous tenant's name", "Only the size of a storage cupboard"], "Location should be assessed in relation to access and demand."),
    ("perishable", "food-service-inventory", 1, "Why is ordering the right amount especially important in food service?", "Much of the stock is perishable", ["Food never loses usable life", "All inventory can be held indefinitely", "Purchases cannot affect operating cost"], "Perishability makes purchasing and inventory management important."),
    ("more-revenue", "food-service-revenue", 3, "A cafe offers existing diners an optional dessert using its current space. Which aim is most directly illustrated?", "Increasing revenue from existing customers and capacity", ["Only acquiring an entirely new market", "Only reducing property rent", "Only increasing equipment depreciation"], "The example adds an optional sale to an existing encounter."),
    ("new-patrons", "food-service-revenue", 3, "A targeted offer brings first-time diners from the local area. Which aim is most directly addressed?", "Increasing the operation's share of potential customers", ["Only increasing spend from the same diners", "Only changing the payroll schedule", "Only reducing table-cleaning time"], "The offer aims to attract new patrons."),
    ("cost-pressure", "food-service-costs", 3, "Sales remain steady while ingredient waste rises. What operational issue should management investigate?", "Purchasing, stock handling and use that affect food cost", ["Assume steady revenue guarantees steady profit", "Consider only the number of online followers", "Increase orders without examining the waste"], "Cost control matters alongside revenue."),
])

_lesson("https://www.lean.org/lexicon-terms/pull-production/", "inventory",
        "Pull production: replenishment, sequence and product mix", "Lean Enterprise Institute",
        "Downstream demand signals, supermarket replenishment, sequential pull and mixed systems. Scope is the public definition; no optimisation guarantee or full implementation prescription.",
        ("Pull Production", "Supermarket Pull System", "Sequential Pull System", "Mixed Supermarket and Sequential Pull System"), [
    ("signal", "pull-trigger", 1, "What triggers upstream production in a pull system?", "A downstream signal of need", ["Unused capacity alone", "Only a desire to maximise every machine's output", "A rule to produce regardless of consumption"], "The downstream activity communicates what it needs."),
    ("supermarket", "pull-supermarket", 2, "What does a supermarket pull process replenish?", "What was withdrawn from its product store", ["Every product to an unlimited level", "Only the most expensive product regardless of use", "Only a forecast unrelated to actual withdrawal"], "Withdrawals authorise replacement."),
    ("sequential", "pull-sequential", 1, "When can sequential pull be useful?", "When there are too many part numbers to stock every one in a supermarket", ["When no customer order information exists and lead time is unlimited", "When FIFO must always be abandoned", "When every item should be produced without a signal"], "Sequential pull can handle a large variety of made-to-order items."),
    ("replace", "pull-supermarket", 3, "A downstream process withdraws two authorised containers of a part. What does supermarket pull normally signal upstream?", "Replace the withdrawn quantity", ["Fill every available shelf regardless of demand", "Produce a different part with spare capacity", "Double all future container sizes automatically"], "The replenishment signal follows the withdrawal."),
    ("fifo", "pull-sequential", 3, "A sequential system passes a list of individual orders through several steps. Which discipline does the page require?", "Maintain their first-in, first-out sequence", ["Let each step independently choose its favourite order", "Always process the newest order first", "Group everything only by whichever batch is largest"], "Order sequence must be preserved through the system."),
    ("mixed", "pull-mix", 3, "A few part numbers account for most daily volume while many others are infrequent orders. Which described option may fit?", "A mixed supermarket and sequential system", ["One supermarket containing unlimited stock of every part", "Producing every rare item every day regardless of orders", "Removing all downstream signals"], "Different demand segments can use different pull approaches."),
])

_lesson("https://www.atlassian.com/team-playbook/plays/retrospective", "projects",
        "Retrospectives: feedback, patterns and owned improvements", "Atlassian",
        "A no-blame retrospective gathers different perspectives, identifies useful patterns and assigns improvement actions with owners/deadlines. No AI tool or fixed ritual is required for these checks.",
        ("Set the tone", "Gather feedback", "Turn feedback into insights", "Create action items"), [
    ("purpose", "retro-purpose", 1, "What is the main aim of a retrospective?", "Learn from completed work and improve the next cycle", ["Only repeat the status update", "Only assign personal blame", "Only approve a final invoice"], "Reflection should lead to improvements in future work."),
    ("tone", "retro-safety", 2, "Which tone supports useful retrospective feedback?", "Respectful, honest and focused on improvement", ["Punishing people for raising problems", "Allowing only favourable comments", "Treating disagreement as disloyalty"], "A no-blame setting helps people share relevant experience."),
    ("action", "retro-actions", 1, "What should accompany a retrospective action item?", "An owner and a deadline", ["Only a vague wish", "Only an anonymous suggestion with no follow-up", "Only a declaration that the discussion is over"], "Ownership and timing support implementation."),
    ("voices", "retro-feedback", 3, "One participant dominates and others have not contributed. What should the facilitator do?", "Invite other perspectives and use a suitable feedback structure", ["Treat the longest contribution as the complete evidence", "End feedback collection immediately", "Allow only the most senior person to speak"], "Different perspectives improve the feedback available."),
    ("patterns", "retro-insights", 3, "Several reports describe the same recurring handoff delay. What should the group investigate?", "The shared pattern and a change that may improve it", ["Only the most amusing isolated event", "Only who wrote the shortest note", "Whether the repeated reports can be removed from the record"], "Patterns can reveal valuable process improvements."),
    ("follow-through", "retro-actions", 3, "The team repeatedly agrees improvements but none reach the work plan. What is a useful next step?", "Put owned, dated actions into the team's task system and follow up", ["Hold longer discussions without recording commitments", "Assume agreement is equivalent to implementation", "Stop checking whether actions were completed"], "Actions need a visible path into actual work."),
])

_lesson("https://www.lean.org/lexicon-terms/takt-time/", "supply-chain",
        "Takt time: calculate the pace of customer demand", "Lean Enterprise Institute",
        "Available production time divided by demand, consistent units and how the required interval changes with demand. Fictional arithmetic; not a capacity feasibility or staffing model.",
        ("Takt Time", "Available production time divided by customer demand"), [
    ("formula", "takt-formula", 1, "How is takt time calculated?", "Available production time divided by customer demand", ["Customer demand divided by available time", "Total revenue divided by inventory", "Available time multiplied by demand"], "Takt expresses the time available per demanded unit."),
    ("purpose", "takt-purpose", 1, "What is the purpose of takt time?", "Set a production pace aligned with customer demand", ["Prove that every process can already meet demand", "Maximise output regardless of customer need", "Replace all measurement of available time"], "Takt describes the pace needed to match demand."),
    ("units", "takt-units", 2, "If available time is measured in minutes and demand in units, what are the takt units?", "Minutes per unit", ["Units per minute", "Units squared", "A percentage of revenue"], "Dividing minutes by units gives a time interval per unit."),
    ("calculate", "takt-formula", 3, "A process has 420 available minutes and demand for 140 units in the same period. What is takt time?", "3 minutes per unit", ["0.333 minutes per unit", "280 minutes per unit", "560 minutes per unit"], "420 ÷ 140 = 3 minutes per unit."),
    ("higher-demand", "takt-demand-change", 3, "Available time stays at 360 minutes while demand rises from 120 to 180 units. What happens to takt?", "It falls from 3 to 2 minutes per unit", ["It rises from 2 to 3 minutes per unit", "It remains 3 minutes per unit", "It becomes 180 minutes per unit"], "More demanded units in the same time require a shorter interval."),
    ("period", "takt-units", 3, "An analyst divides one week's available minutes by one day's demand. What should be corrected first?", "Use available time and demand for the same period", ["Treat the result as valid because both numbers are positive", "Replace demand with the stock balance", "Multiply by revenue to remove the time mismatch"], "The numerator and denominator must refer to a consistent demand period."),
])
